1	//! OS service management for running LunarWing as a daemon.
2	//!
3	//! Generates and manages platform-native service definitions:
4	//! - **macOS**: launchd plist at `~/Library/LaunchAgents/com.lunarwing.daemon.plist`
5	//! - **Linux/systemd**: user unit at `~/.config/systemd/user/lunarwing.service`
6	//! - **Linux/OpenRC**: init script at `/etc/init.d/lunarwing`
7	//!
8	//! The installed service runs `ironclaw run` (the default agent mode) and is
9	//! configured to restart automatically on failure.
10	
11	use std::path::{Path, PathBuf};
12	use std::process::Command;
13	#[cfg(unix)]
14	use std::{fs::Permissions, os::unix::fs::PermissionsExt};
15	
16	use anyhow::{Context, Result, bail};
17	
18	use crate::bootstrap::ironclaw_base_dir;
19	
20	const SERVICE_LABEL: &str = "com.lunarwing.daemon";
21	const LEGACY_SERVICE_LABEL: &str = "com.ironclaw.daemon";
22	const SYSTEMD_UNIT: &str = "lunarwing.service";
23	const LEGACY_SYSTEMD_UNIT: &str = "ironclaw.service";
24	const SYSTEMD_XMPP_BRIDGE_UNIT: &str = "xmpp-bridge.service";
25	const OPENRC_UNIT: &str = "lunarwing";
26	const OPENRC_XMPP_BRIDGE_UNIT: &str = "xmpp-bridge";
27	const OPENRC_LUNARWING_INIT: &str = include_str!("../systemd/lunarwing.openrc");
28	const OPENRC_XMPP_BRIDGE_INIT: &str = include_str!("../systemd/xmpp-bridge.openrc");
29	const OPENRC_LUNARWING_ENV_TEMPLATE: &str = "# Optional environment overrides for LunarWing.\n\
30	# Add secrets or one-off overrides here when they must not live in config.toml.\n\
31	# Example to override the runtime banner / agent identity:\n\
32	# AGENT_NAME=lunarwing\n\
33	# Example defaults used by the launcher and service path for local/private infra:\n\
34	# ALLOW_PRIVATE_IPS=1\n\
35	# PGSSLMODE=disable\n\
36	# Example for OpenAI-compatible endpoints that insist on a placeholder key:\n\
37	# LLM_API_KEY=unneeded\n";
38	const OPENRC_XMPP_BRIDGE_ENV_TEMPLATE: &str =
39	    "# Optional environment overrides for the LunarWing XMPP bridge.\n";
40	
41	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
42	pub enum ServiceManager {
43	    Launchd,
44	    SystemdUser,
45	    OpenRc,
46	}
47	
48	impl ServiceManager {
49	    pub fn display_name(self) -> &'static str {
50	        match self {
51	            ServiceManager::Launchd => "launchd",
52	            ServiceManager::SystemdUser => "systemd user",
53	            ServiceManager::OpenRc => "OpenRC",
54	        }
55	    }
56	
57	    pub(crate) fn install_artifact(self) -> &'static str {
58	        match self {
59	            ServiceManager::Launchd => "launchd plist",
60	            ServiceManager::SystemdUser => "systemd user unit",
61	            ServiceManager::OpenRc => "OpenRC service",
62	        }
63	    }
64	}
65	
66	#[derive(Debug, Clone)]
67	pub struct ServiceInstallation {
68	    pub manager: ServiceManager,
69	    pub path: PathBuf,
70	}
71	
72	#[derive(Debug, Clone)]
73	pub struct SetupServiceOffer {
74	    pub manager: ServiceManager,
75	    pub can_install_now: bool,
76	    pub install_command: Option<String>,
77	}
78	
79	// ── Public dispatch ─────────────────────────────────────────────
80	
81	pub fn detected_service_manager() -> Result<ServiceManager> {
82	    if cfg!(target_os = "macos") {
83	        Ok(ServiceManager::Launchd)
84	    } else if cfg!(target_os = "linux") {
85	        detect_linux_service_manager()
86	    } else {
87	        bail!("Service management is only supported on macOS and Linux");
88	    }
89	}
90	
91	pub fn service_installation() -> Result<ServiceInstallation> {
92	    let manager = detected_service_manager()?;
93	    let path = match manager {
94	        ServiceManager::Launchd => macos_plist_path()?,
95	        ServiceManager::SystemdUser => linux_unit_path()?,
96	        ServiceManager::OpenRc => linux_openrc_init_path(OPENRC_UNIT),
97	    };
98	    Ok(ServiceInstallation { manager, path })
99	}
100	
101	pub fn setup_service_offer() -> Result<Option<SetupServiceOffer>> {
102	    if !cfg!(target_os = "macos") && !cfg!(target_os = "linux") {
103	        return Ok(None);
104	    }
105	
106	    let manager = detected_service_manager()?;
107	    let can_install_now = match manager {
108	        ServiceManager::Launchd | ServiceManager::SystemdUser => true,
109	        ServiceManager::OpenRc => is_effective_root(),
110	    };
111	    let install_command = if can_install_now || manager != ServiceManager::OpenRc {
112	        None
113	    } else {
114	        Some(openrc_command_hint("install")?)
115	    };
116	
117	    Ok(Some(SetupServiceOffer {
118	        manager,
119	        can_install_now,
120	        install_command,
121	    }))
122	}
123	
124	/// Route a service subcommand to the appropriate handler.
125	pub fn handle_command(command: &ServiceAction) -> Result<()> {
126	    match command {
127	        ServiceAction::Install => install(),
128	        ServiceAction::Start => start(),
129	        ServiceAction::Stop => stop(),
130	        ServiceAction::Status => status(),
131	        ServiceAction::Uninstall => uninstall(),
132	    }
133	}
134	
135	/// The five service lifecycle actions.
136	#[derive(Debug, Clone)]
137	pub enum ServiceAction {
138	    Install,
139	    Start,
140	    Stop,
141	    Status,
142	    Uninstall,
143	}
144	
145	// ── Install ─────────────────────────────────────────────────────
146	
147	fn install() -> Result<()> {
148	    match detected_service_manager()? {
149	        ServiceManager::Launchd => install_macos(),
150	        ServiceManager::SystemdUser => install_linux_systemd_user(),
151	        ServiceManager::OpenRc => install_linux_openrc(),
152	    }
153	}
154	
155	fn install_macos() -> Result<()> {
156	    let file = macos_plist_path()?;
157	    if let Some(parent) = file.parent() {
158	        std::fs::create_dir_all(parent)?;
159	    }
160	
161	    let exe = std::env::current_exe().context("failed to resolve current executable")?;
162	    let logs_dir = ironclaw_logs_dir();
163	    std::fs::create_dir_all(&logs_dir)?;
164	
165	    let stdout = logs_dir.join("daemon.stdout.log");
166	    let stderr = logs_dir.join("daemon.stderr.log");
167	
168	    let plist = macos_plist_content(
169	        &exe.display().to_string(),
170	        &stdout.display().to_string(),
171	        &stderr.display().to_string(),
172	    );
173	
174	    std::fs::write(&file, plist)?;
175	    disable_legacy_macos_service().ok();
176	    println!("Installed launchd service: {}", file.display());
177	    println!("  Start with: ironclaw service start");
178	    Ok(())
179	}
180	
181	fn macos_plist_content(exe: &str, stdout: &str, stderr: &str) -> String {
182	    format!(
183	        r#"<?xml version="1.0" encoding="UTF-8"?>
184	<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
185	<plist version="1.0">
186	<dict>
187	  <key>Label</key>
188	  <string>{label}</string>
189	  <key>ProgramArguments</key>
190	  <array>
191	    <string>{exe}</string>
192	    <string>run</string>
193	  </array>
194	  <key>RunAtLoad</key>
195	  <true/>
196	  <key>KeepAlive</key>
197	  <true/>
198	  <!-- Disable interactive CLI/REPL in daemon mode to prevent blocking on stdin -->
199	  <key>EnvironmentVariables</key>
200	  <dict>
201	    <key>CLI_ENABLED</key>
202	    <string>false</string>
203	  </dict>
204	  <key>StandardOutPath</key>
205	  <string>{stdout}</string>
206	  <key>StandardErrorPath</key>
207	  <string>{stderr}</string>
208	</dict>
209	</plist>
210	"#,
211	        label = SERVICE_LABEL,
212	        exe = xml_escape(exe),
213	        stdout = xml_escape(stdout),
214	        stderr = xml_escape(stderr),
215	    )
216	}
217	
218	fn install_linux_systemd_user() -> Result<()> {
219	    let file = linux_unit_path()?;
220	    if let Some(parent) = file.parent() {
221	        std::fs::create_dir_all(parent)?;
222	    }
223	
224	    let exe = std::env::current_exe().context("failed to resolve current executable")?;
225	    let bridge_exe = linux_bridge_executable_path(&exe);
226	    let unit = linux_unit_content(&exe, bridge_exe.is_some());
227	
228	    std::fs::write(&file, unit)?;
229	    if let Some(bridge_exe) = bridge_exe {
230	        let bridge_file = linux_xmpp_bridge_unit_path()?;
231	        std::fs::write(&bridge_file, linux_xmpp_bridge_unit_content(&bridge_exe))?;
232	    }
233	    disable_legacy_linux_unit().ok();
234	    run_checked(Command::new("systemctl").args(["--user", "daemon-reload"])).ok();
235	    run_checked(Command::new("systemctl").args(["--user", "enable", SYSTEMD_UNIT])).ok();
236	    if linux_xmpp_bridge_unit_path()?.exists() {
237	        run_checked(Command::new("systemctl").args(["--user", "enable", SYSTEMD_XMPP_BRIDGE_UNIT]))
238	            .ok();
239	    }
240	    println!("Installed systemd user service: {}", file.display());
241	    if let Some(bridge_exe) = linux_bridge_executable_path(&exe) {
242	        println!(
243	            "Installed XMPP bridge user service: {} ({})",
244	            linux_xmpp_bridge_unit_path()?.display(),
245	            bridge_exe.display()
246	        );
247	    } else {
248	        println!(
249	            "Skipped XMPP bridge user service install: bridge binary not found next to this checkout"
250	        );
251	    }
252	    println!("  Start with: ironclaw service start");
253	    Ok(())
254	}
255	
256	fn install_linux_openrc() -> Result<()> {
257	    ensure_openrc_root("install")?;
258	
259	    let exe = std::env::current_exe().context("failed to resolve current executable")?;
260	    let base_dir = ironclaw_base_dir();
261	    let logs_dir = base_dir.join("logs");
262	    let bridge_exe = linux_bridge_executable_path(&exe);
263	    let (service_user, service_group) = current_service_identity();
264	
265	    write_text_file_with_mode(
266	        &linux_openrc_init_path(OPENRC_UNIT),
267	        OPENRC_LUNARWING_INIT,
268	        0o755,
269	    )?;
270	    write_text_file_with_mode(
271	        &linux_openrc_confd_path(OPENRC_UNIT),
272	        &linux_openrc_confd_content(
273	            &exe,
274	            &base_dir,
275	            &logs_dir,
276	            &service_user,
277	            &service_group,
278	            bridge_exe.is_some(),
279	        ),
280	        0o644,
281	    )?;
282	    ensure_text_file_with_mode(
283	        &linux_openrc_env_path("lunarwing.env"),
284	        OPENRC_LUNARWING_ENV_TEMPLATE,
285	        0o600,
286	    )?;
287	
288	    run_checked(Command::new("rc-update").args(["add", OPENRC_UNIT, "default"])).ok();
289	
290	    println!(
291	        "Installed OpenRC service: {}",
292	        linux_openrc_init_path(OPENRC_UNIT).display()
293	    );
294	    println!(
295	        "Installed OpenRC config: {}",
296	        linux_openrc_confd_path(OPENRC_UNIT).display()
297	    );
298	
299	    if let Some(bridge_exe) = bridge_exe {
300	        write_text_file_with_mode(
301	            &linux_openrc_init_path(OPENRC_XMPP_BRIDGE_UNIT),
302	            OPENRC_XMPP_BRIDGE_INIT,
303	            0o755,
304	        )?;
305	        write_text_file_with_mode(
306	            &linux_openrc_confd_path(OPENRC_XMPP_BRIDGE_UNIT),
307	            &linux_openrc_bridge_confd_content(
308	                &bridge_exe,
309	                &base_dir,
310	                &logs_dir,
311	                &service_user,
312	                &service_group,
313	            ),
314	            0o644,
315	        )?;
316	        ensure_text_file_with_mode(
317	            &linux_openrc_env_path("xmpp-bridge.env"),
318	            OPENRC_XMPP_BRIDGE_ENV_TEMPLATE,
319	            0o600,
320	        )?;
321	        run_checked(Command::new("rc-update").args(["add", OPENRC_XMPP_BRIDGE_UNIT, "default"]))
322	            .ok();
323	        println!(
324	            "Installed OpenRC XMPP bridge service: {} ({})",
325	            linux_openrc_init_path(OPENRC_XMPP_BRIDGE_UNIT).display(),
326	            bridge_exe.display()
327	        );
328	    } else {
329	        println!(
330	            "Skipped OpenRC XMPP bridge install: bridge binary not found next to this checkout"
331	        );
332	    }
333	
334	    println!("  Start with: ironclaw service start");
335	    Ok(())
336	}
337	
338	// ── Start ───────────────────────────────────────────────────────
339	
340	fn start() -> Result<()> {
341	    match detected_service_manager()? {
342	        ServiceManager::Launchd => {
343	            let plist = macos_plist_path()?;
344	            if !plist.exists() {
345	                bail!("Service not installed. Run `ironclaw service install` first.");
346	            }
347	            run_checked(Command::new("launchctl").arg("load").arg("-w").arg(&plist))?;
348	            run_checked(Command::new("launchctl").arg("start").arg(SERVICE_LABEL))?;
349	            println!("Service started");
350	            Ok(())
351	        }
352	        ServiceManager::SystemdUser => {
353	            run_checked(Command::new("systemctl").args(["--user", "daemon-reload"]))?;
354	            if linux_xmpp_bridge_unit_path()?.exists() {
355	                run_checked(Command::new("systemctl").args([
356	                    "--user",
357	                    "start",
358	                    SYSTEMD_XMPP_BRIDGE_UNIT,
359	                ]))
360	                .ok();
361	            }
362	            run_checked(Command::new("systemctl").args(["--user", "start", SYSTEMD_UNIT]))?;
363	            println!("Service started");
364	            Ok(())
365	        }
366	        ServiceManager::OpenRc => start_linux_openrc(),
367	    }
368	}
369	
370	// ── Stop ────────────────────────────────────────────────────────
371	
372	fn stop() -> Result<()> {
373	    match detected_service_manager()? {
374	        ServiceManager::Launchd => {
375	            let plist = macos_plist_path()?;
376	            run_checked(Command::new("launchctl").arg("stop").arg(SERVICE_LABEL)).ok();
377	            run_checked(
378	                Command::new("launchctl")
379	                    .arg("unload")
380	                    .arg("-w")
381	                    .arg(&plist),
382	            )
383	            .ok();
384	            println!("Service stopped");
385	            Ok(())
386	        }
387	        ServiceManager::SystemdUser => {
388	            run_checked(Command::new("systemctl").args(["--user", "stop", SYSTEMD_UNIT])).ok();
389	            if linux_xmpp_bridge_unit_path()?.exists() {
390	                run_checked(Command::new("systemctl").args([
391	                    "--user",
392	                    "stop",
393	                    SYSTEMD_XMPP_BRIDGE_UNIT,
394	                ]))
395	                .ok();
396	            }
397	            println!("Service stopped");
398	            Ok(())
399	        }
400	        ServiceManager::OpenRc => stop_linux_openrc(),
401	    }
402	}
403	
404	// ── Status ──────────────────────────────────────────────────────
405	
406	fn status() -> Result<()> {
407	    match detected_service_manager()? {
408	        ServiceManager::Launchd => {
409	            let out = run_capture(Command::new("launchctl").arg("list"))?;
410	            let running = out.lines().any(|line| line.contains(SERVICE_LABEL));
411	            println!(
412	                "Service: {}",
413	                if running {
414	                    "running/loaded"
415	                } else {
416	                    "not loaded"
417	                }
418	            );
419	            println!("Unit: {}", macos_plist_path()?.display());
420	            Ok(())
421	        }
422	        ServiceManager::SystemdUser => {
423	            let state =
424	                run_capture(Command::new("systemctl").args(["--user", "is-active", SYSTEMD_UNIT]))
425	                    .unwrap_or_else(|_| "unknown".into());
426	            println!("Service state: {}", state.trim());
427	            println!("Unit: {}", linux_unit_path()?.display());
428	            let bridge_file = linux_xmpp_bridge_unit_path()?;
429	            if bridge_file.exists() {
430	                let bridge_state = run_capture(Command::new("systemctl").args([
431	                    "--user",
432	                    "is-active",
433	                    SYSTEMD_XMPP_BRIDGE_UNIT,
434	                ]))
435	                .unwrap_or_else(|_| "unknown".into());
436	                println!("XMPP bridge state: {}", bridge_state.trim());
437	                println!("XMPP bridge unit: {}", bridge_file.display());
438	            }
439	            Ok(())
440	        }
441	        ServiceManager::OpenRc => status_linux_openrc(),
442	    }
443	}
444	
445	// ── Uninstall ───────────────────────────────────────────────────
446	
447	fn uninstall() -> Result<()> {
448	    // Stop first (ignore errors, service might not be running)
449	    stop().ok();
450	
451	    match detected_service_manager()? {
452	        ServiceManager::Launchd => {
453	            let file = macos_plist_path()?;
454	            if file.exists() {
455	                std::fs::remove_file(&file)
456	                    .with_context(|| format!("failed to remove {}", file.display()))?;
457	            }
458	            println!("Service uninstalled ({})", file.display());
459	            Ok(())
460	        }
461	        ServiceManager::SystemdUser => uninstall_linux_systemd_user(),
462	        ServiceManager::OpenRc => uninstall_linux_openrc(),
463	    }
464	}
