466	// ── Path helpers ────────────────────────────────────────────────
467	
468	fn macos_plist_path() -> Result<PathBuf> {
469	    let home = dirs::home_dir().context("could not find home directory")?;
470	    Ok(home
471	        .join("Library")
472	        .join("LaunchAgents")
473	        .join(format!("{SERVICE_LABEL}.plist")))
474	}
475	
476	fn linux_unit_path() -> Result<PathBuf> {
477	    Ok(linux_systemd_unit_dir()?.join(SYSTEMD_UNIT))
478	}
479	
480	fn linux_xmpp_bridge_unit_path() -> Result<PathBuf> {
481	    Ok(linux_systemd_unit_dir()?.join(SYSTEMD_XMPP_BRIDGE_UNIT))
482	}
483	
484	fn linux_legacy_unit_path() -> Result<PathBuf> {
485	    Ok(linux_systemd_unit_dir()?.join(LEGACY_SYSTEMD_UNIT))
486	}
487	
488	fn linux_systemd_unit_dir() -> Result<PathBuf> {
489	    let home = dirs::home_dir().context("could not find home directory")?;
490	    Ok(home.join(".config").join("systemd").join("user"))
491	}
492	
493	fn linux_openrc_init_path(name: &str) -> PathBuf {
494	    PathBuf::from("/etc/init.d").join(name)
495	}
496	
497	fn linux_openrc_confd_path(name: &str) -> PathBuf {
498	    PathBuf::from("/etc/conf.d").join(name)
499	}
500	
501	fn linux_openrc_env_path(name: &str) -> PathBuf {
502	    PathBuf::from("/etc/lunarwing").join(name)
503	}
504	
505	fn linux_openrc_env_dir() -> PathBuf {
506	    PathBuf::from("/etc/lunarwing")
507	}
508	
509	fn ironclaw_logs_dir() -> PathBuf {
510	    ironclaw_base_dir().join("logs")
511	}
512	
513	fn disable_legacy_linux_unit() -> Result<()> {
514	    if LEGACY_SYSTEMD_UNIT == SYSTEMD_UNIT {
515	        return Ok(());
516	    }
517	
518	    let legacy_file = linux_legacy_unit_path()?;
519	    if !legacy_file.exists() {
520	        return Ok(());
521	    }
522	
523	    match run_checked(Command::new("systemctl").args([
524	        "--user",
525	        "disable",
526	        "--now",
527	        LEGACY_SYSTEMD_UNIT,
528	    ])) {
529	        Ok(()) => println!(
530	            "Disabled legacy systemd user service: {}",
531	            legacy_file.display()
532	        ),
533	        Err(e) => println!(
534	            "Legacy systemd user service still exists at {}. \
535	             Disable it manually to avoid running two daemons: {}",
536	            legacy_file.display(),
537	            e
538	        ),
539	    }
540	
541	    Ok(())
542	}
543	
544	fn disable_legacy_macos_service() -> Result<()> {
545	    if LEGACY_SERVICE_LABEL == SERVICE_LABEL {
546	        return Ok(());
547	    }
548	
549	    let home = dirs::home_dir().context("could not find home directory")?;
550	    let legacy_file = home
551	        .join("Library")
552	        .join("LaunchAgents")
553	        .join(format!("{LEGACY_SERVICE_LABEL}.plist"));
554	    if !legacy_file.exists() {
555	        return Ok(());
556	    }
557	
558	    run_checked(
559	        Command::new("launchctl")
560	            .arg("stop")
561	            .arg(LEGACY_SERVICE_LABEL),
562	    )
563	    .ok();
564	    match run_checked(
565	        Command::new("launchctl")
566	            .arg("unload")
567	            .arg("-w")
568	            .arg(&legacy_file),
569	    ) {
570	        Ok(()) => println!("Unloaded legacy launchd service: {}", legacy_file.display()),
571	        Err(e) => println!(
572	            "Legacy launchd service still exists at {}. \
573	             Unload it manually to avoid running two daemons: {}",
574	            legacy_file.display(),
575	            e
576	        ),
577	    }
578	
579	    Ok(())
580	}
581	
582	fn linux_unit_content(exe: &Path, include_xmpp_bridge: bool) -> String {
583	    let bridge_unit_lines = if include_xmpp_bridge {
584	        format!(
585	            "Wants={bridge}\n\
586	             After=network.target {bridge}\n",
587	            bridge = SYSTEMD_XMPP_BRIDGE_UNIT
588	        )
589	    } else {
590	        "After=network.target\n".to_string()
591	    };
592	
593	    format!(
594	        "[Unit]\n\
595	         Description=LunarWing daemon\n\
596	         {bridge_unit_lines}\
597	         \n\
598	         [Service]\n\
599	         Type=simple\n\
600	         # Disable interactive CLI/REPL in daemon mode to prevent blocking on stdin\n\
601	         Environment=\"CLI_ENABLED=false\"\n\
602	         Environment=\"AGENT_NAME=lunarwing\"\n\
603	         Environment=\"ALLOW_PRIVATE_IPS=1\"\n\
604	         Environment=\"PGSSLMODE=disable\"\n\
605	         ExecStart=\"{exe}\" run\n\
606	         Restart=always\n\
607	         RestartSec=3\n\
608	         \n\
609	         [Install]\n\
610	         WantedBy=default.target\n",
611	        exe = exe.display(),
612	        bridge_unit_lines = bridge_unit_lines,
613	    )
614	}
615	
616	fn linux_xmpp_bridge_unit_content(exe: &Path) -> String {
617	    format!(
618	        "[Unit]\n\
619	         Description=LunarWing XMPP bridge\n\
620	         After=network.target\n\
621	         PartOf={main_unit}\n\
622	         \n\
623	         [Service]\n\
624	         Type=simple\n\
625	         ExecStart=\"{exe}\"\n\
626	         Restart=always\n\
627	         RestartSec=3\n\
628	         \n\
