636	fn linux_bridge_executable_path(ironclaw_exe: &Path) -> Option<PathBuf> {
637	    if let Ok(explicit) = std::env::var("XMPP_BRIDGE_EXECUTABLE") {
638	        let path = PathBuf::from(explicit.trim());
639	        if path.is_file() {
640	            return Some(path);
641	        }
642	    }
643	
644	    let mut candidates = Vec::new();
645	
646	    if let Some(exe_dir) = ironclaw_exe.parent() {
647	        candidates.push(exe_dir.join("xmpp-bridge"));
648	
649	        if let (Some(target_dir), Some(profile_dir_name)) = (exe_dir.parent(), exe_dir.file_name())
650	            && let Some(repo_root) = target_dir.parent()
651	        {
652	            candidates.push(
653	                repo_root
654	                    .join("bridges")
655	                    .join("xmpp-bridge")
656	                    .join("target")
657	                    .join(profile_dir_name)
658	                    .join("xmpp-bridge"),
659	            );
660	        }
661	    }
662	
663	    candidates.into_iter().find(|path| path.is_file())
664	}
