1009	#[derive(Debug, Clone, Copy, Default)]
1010	struct LinuxServiceProbe<'a> {
1011	    override_value: Option<&'a str>,
1012	    has_openrc_runtime: bool,
1013	    has_systemd_runtime: bool,
1014	    has_rc_service: bool,
1015	    has_rc_update: bool,
1016	    has_systemctl: bool,
1017	}
1018	
1019	fn detect_linux_service_manager_from_probe(
1020	    probe: &LinuxServiceProbe<'_>,
1021	) -> Result<ServiceManager> {
1022	    if let Some(override_value) = probe.override_value {
1023	        let normalized = override_value.trim().to_ascii_lowercase();
1024	        return match normalized.as_str() {
1025	            "systemd" | "systemd-user" => Ok(ServiceManager::SystemdUser),
1026	            "openrc" => Ok(ServiceManager::OpenRc),
1027	            other => bail!(
1028	                "Unsupported service manager override '{}'. Use 'systemd' or 'openrc'.",
1029	                other
1030	            ),
1031	        };
1032	    }
1033	
1034	    if probe.has_openrc_runtime {
1035	        return Ok(ServiceManager::OpenRc);
1036	    }
1037	    if probe.has_systemd_runtime {
1038	        return Ok(ServiceManager::SystemdUser);
1039	    }
1040	    if probe.has_rc_service && probe.has_rc_update && !probe.has_systemctl {
1041	        return Ok(ServiceManager::OpenRc);
1042	    }
1043	    if probe.has_systemctl {
1044	        return Ok(ServiceManager::SystemdUser);
1045	    }
1046	    if probe.has_rc_service && probe.has_rc_update {
1047	        return Ok(ServiceManager::OpenRc);
1048	    }
1049	
1050	    bail!(
1051	        "Could not detect a supported Linux service manager. \
1052	         Set LUNARWING_SERVICE_MANAGER=systemd or LUNARWING_SERVICE_MANAGER=openrc \
1053	         (legacy IRONCLAW_SERVICE_MANAGER is also supported)."
1054	    )
1055	}
