1	//! OS keychain integration for secrets master key storage.
2	//!
3	//! Provides platform-specific keychain support:
4	//! - macOS: security-framework (Keychain Services)
5	//! - Linux: secret-service (GNOME Keyring, KWallet)
6	//!
7	//! # Example
8	//!
9	//! ```ignore
10	//! use ironclaw::secrets::keychain::{store_master_key, get_master_key, delete_master_key};
11	//!
12	//! // Generate and store a new master key
13	//! let key = generate_master_key();
14	//! store_master_key(&key)?;
15	//!
16	//! // Later, retrieve it
17	//! let key = get_master_key()?;
18	//! ```
19	
20	use crate::secrets::SecretError;
21	
22	/// Service name for keychain entries.
23	#[cfg(any(target_os = "macos", target_os = "linux"))]
24	const SERVICE_NAME: &str = "ironclaw";
25	
26	/// Account name for the master key.
27	#[cfg(any(target_os = "macos", target_os = "linux"))]
28	const MASTER_KEY_ACCOUNT: &str = "master_key";
29	
30	/// Generate a random 32-byte master key.
31	pub fn generate_master_key() -> Vec<u8> {
32	    use rand::RngCore;
33	    use rand::rngs::OsRng;
34	    let mut key = vec![0u8; 32];
35	    OsRng.fill_bytes(&mut key);
36	    key
37	}
38	
39	/// Generate a master key as a hex string.
40	pub fn generate_master_key_hex() -> String {
41	    let bytes = generate_master_key();
42	    bytes.iter().map(|b| format!("{:02x}", b)).collect()
43	}
