46	// macOS implementation using security-framework
47	// ============================================================================
48	
49	#[cfg(target_os = "macos")]
50	mod platform {
51	    use security_framework::passwords::{
52	        delete_generic_password, get_generic_password, set_generic_password,
53	    };
54	
55	    use super::*;
56	
57	    /// Store the master key in the macOS Keychain.
58	    pub async fn store_master_key(key: &[u8]) -> Result<(), SecretError> {
59	        // Convert to hex for storage (keychain prefers strings)
60	        let key_hex: String = key.iter().map(|b| format!("{:02x}", b)).collect();
61	
62	        set_generic_password(SERVICE_NAME, MASTER_KEY_ACCOUNT, key_hex.as_bytes())
63	            .map_err(|e| SecretError::KeychainError(format!("Failed to store in keychain: {}", e)))
64	    }
65	
66	    /// Retrieve the master key from the macOS Keychain.
67	    pub async fn get_master_key() -> Result<Vec<u8>, SecretError> {
68	        let password = get_generic_password(SERVICE_NAME, MASTER_KEY_ACCOUNT).map_err(|e| {
69	            SecretError::KeychainError(format!("Failed to get from keychain: {}", e))
70	        })?;
71	
72	        // Parse hex string back to bytes
73	        let hex_str = String::from_utf8(password)
74	            .map_err(|_| SecretError::KeychainError("Invalid UTF-8 in keychain".to_string()))?;
75	
76	        hex_to_bytes(&hex_str)
77	    }
78	
79	    /// Delete the master key from the macOS Keychain.
80	    pub async fn delete_master_key() -> Result<(), SecretError> {
81	        delete_generic_password(SERVICE_NAME, MASTER_KEY_ACCOUNT).map_err(|e| {
82	            SecretError::KeychainError(format!("Failed to delete from keychain: {}", e))
83	        })
84	    }
85	
86	    /// Check if a master key exists in the keychain.
87	    pub async fn has_master_key() -> bool {
88	        get_generic_password(SERVICE_NAME, MASTER_KEY_ACCOUNT).is_ok()
89	    }
90	}
