55	impl SandboxModeConfig {
56	    pub(crate) fn resolve(settings: &crate::settings::Settings) -> Result<Self, ConfigError> {
57	        let ss = &settings.sandbox;
58	
59	        let extra_domains = optional_env("SANDBOX_EXTRA_DOMAINS")?
60	            .map(|s| s.split(',').map(|d| d.trim().to_string()).collect())
61	            .unwrap_or_else(|| {
62	                if ss.extra_allowed_domains.is_empty() {
63	                    Vec::new()
64	                } else {
65	                    ss.extra_allowed_domains.clone()
66	                }
67	            });
68	
69	        // reaper/orphan fields have no Settings counterpart — env > default only.
70	        let reaper_interval_secs: u64 = parse_optional_env("SANDBOX_REAPER_INTERVAL_SECS", 300)?;
71	        let orphan_threshold_secs: u64 = parse_optional_env("SANDBOX_ORPHAN_THRESHOLD_SECS", 600)?;
72	
73	        // Validate that reaper timings are non-zero to prevent tokio::time::interval panics
74	        if reaper_interval_secs == 0 {
75	            return Err(ConfigError::InvalidValue {
76	                key: "SANDBOX_REAPER_INTERVAL_SECS".to_string(),
77	                message: "must be greater than 0".to_string(),
78	            });
79	        }
80	
81	        if orphan_threshold_secs == 0 {
82	            return Err(ConfigError::InvalidValue {
83	                key: "SANDBOX_ORPHAN_THRESHOLD_SECS".to_string(),
84	                message: "must be greater than 0".to_string(),
85	            });
86	        }
87	
88	        Ok(Self {
89	            enabled: parse_bool_env("SANDBOX_ENABLED", ss.enabled)?,
90	            policy: parse_string_env("SANDBOX_POLICY", ss.policy.clone())?,
91	            // allow_full_access has no Settings counterpart — env > default only.
92	            allow_full_access: parse_bool_env("SANDBOX_ALLOW_FULL_ACCESS", false)?,
93	            timeout_secs: parse_optional_env("SANDBOX_TIMEOUT_SECS", ss.timeout_secs)?,
94	            memory_limit_mb: parse_optional_env("SANDBOX_MEMORY_LIMIT_MB", ss.memory_limit_mb)?,
95	            cpu_shares: parse_optional_env("SANDBOX_CPU_SHARES", ss.cpu_shares)?,
96	            image: parse_string_env("SANDBOX_IMAGE", ss.image.clone())?,
97	            auto_pull_image: parse_bool_env("SANDBOX_AUTO_PULL", ss.auto_pull_image)?,
98	            extra_allowed_domains: extra_domains,
99	            reaper_interval_secs,
100	            orphan_threshold_secs,
101	        })
102	    }
103	
104	    /// Convert to SandboxConfig for the sandbox module.
105	    ///
106	    /// If `policy` is `FullAccess` but `allow_full_access` is `false`,
107	    /// the policy is downgraded to `WorkspaceWrite` and an error is logged.
108	    pub fn to_sandbox_config(&self) -> crate::sandbox::SandboxConfig {
109	        use crate::sandbox::SandboxPolicy;
110	        use std::time::Duration;
111	
112	        let mut policy = self.policy.parse().unwrap_or(SandboxPolicy::ReadOnly);
113	
114	        // Double opt-in guard: FullAccess requires SANDBOX_ALLOW_FULL_ACCESS=true
115	        if policy == SandboxPolicy::FullAccess && !self.allow_full_access {
116	            tracing::error!(
117	                "SANDBOX_POLICY=full_access is set but SANDBOX_ALLOW_FULL_ACCESS is not \
118	                 set to 'true'. FullAccess bypasses Docker and runs commands directly on \
119	                 the host. Downgrading to WorkspaceWrite for safety. Set \
120	                 SANDBOX_ALLOW_FULL_ACCESS=true to explicitly enable FullAccess."
121	            );
122	            policy = SandboxPolicy::WorkspaceWrite;
123	        }
124	
125	        let mut allowlist = crate::sandbox::default_allowlist();
126	        allowlist.extend(self.extra_allowed_domains.clone());
127	
128	        crate::sandbox::SandboxConfig {
129	            enabled: self.enabled,
130	            policy,
131	            allow_full_access: self.allow_full_access,
132	            timeout: Duration::from_secs(self.timeout_secs),
133	            memory_limit_mb: self.memory_limit_mb,
134	            cpu_shares: self.cpu_shares,
135	            network_allowlist: allowlist,
136	            image: self.image.clone(),
137	            auto_pull_image: self.auto_pull_image,
138	            proxy_port: 0, // Auto-assign
139	        }
140	    }
141	}
